changeSet.sql:
ALTER TABLE dot11_ssids DROP COLUMN rates;
ALTER TABLE dot11_ssids ADD COLUMN rates double precision[] NOT NULL DEFAULT '{}';

ALTER TABLE dot11_ssids DROP COLUMN infrastructure_types;
ALTER TABLE dot11_ssids ADD COLUMN infrastructure_types text[] NOT NULL DEFAULT '{}';

ALTER TABLE dot11_ssids ADD COLUMN has_wps boolean NOT NULL;
ALTER TABLE dot11_ssids ADD COLUMN security_protocol text NOT NULL;
ALTER TABLE dot11_ssids ADD COLUMN security_suites jsonb NOT NULL;

BEGIN;
ALTER TABLE l4_sessions
ALTER COLUMN session_key TYPE text;
COMMIT;

CREATE INDEX CONCURRENTLY idx_l4_sessions_join
    ON l4_sessions (session_key)
    INCLUDE (tap_uuid, start_time, l4_type, source_address, source_mac);

CREATE INDEX idx_l4_sessions_tap_mrst
    ON l4_sessions (tap_uuid, most_recent_segment_time DESC)
    INCLUDE (session_key, l4_type, state);

CREATE INDEX l4_sessions_source_address_mrst
    ON l4_sessions (source_address, most_recent_segment_time);
CREATE INDEX l4_sessions_destination_address_mrst
    ON l4_sessions (destination_address, most_recent_segment_time);

DELETE FROM assets_attributes WHERE dimension IN ('TCP_STACK', 'TCP_FINGERPRINT', 'TCP_SIGNATURE',
    'TCP_FINGERPRINT_FORWARDED', 'TCP_SERVER_FINGERPRINT', 'TCP_SERVER_SIGNATURE');
DELETE FROM assets_identity_change_findings;
DELETE FROM assets_identity_duplicate_findings;
UPDATE l4_sessions SET fingerprint = NULL, signature = NULL, server_fingerprint = NULL,
    server_signature = NULL WHERE fingerprint IS NOT NULL OR server_fingerprint IS NOT NULL;

-- upsert tables
ALTER TABLE l4_sessions SET (autovacuum_vacuum_scale_factor = 0.01, autovacuum_vacuum_threshold = 1000, autovacuum_analyze_scale_factor = 0.02, fillfactor = 85, autovacuum_vacuum_cost_delay = 0);
